def get_vcu_webem_credentials(gnb_index=0):
    credentials = {}
    ci_framework_type = get_builtin_value('CI_FRAMEWORK_TYPE')
    if ci_framework_type == 'BFAT':
        logger.warn('Get vcu webem credentials from BFAT environment')
        pass
    else:
        logger.info('Get vcu webem credentials from testline configuration')
        gnb = _get_gnb_object(gnb_id=gnb_index)

        if isinstance(gnb, CloudBts):
            credentials = {
                'ip': gnb.cu.oam_http_connection_details.addr,
                'username': gnb.cu.oam_http_connection_details.username,
                'password': gnb.cu.oam_http_connection_details.password,
            }

    return credentials


def _normalize_host_for_base_url(host):
    host = host.rstrip("]").lstrip("[")
    try:
        if isinstance(ip_address(u(str(host))), IPv6Address):
            return '[{}]'.format(host)
        else:
            return host
    except (ValueError, TypeError):
        return host


