def get_all_pa_ports():
    all_pa_ports_list = []
    ci_framework_type = get_builtin_value('CI_FRAMEWORK_TYPE')
    if ci_framework_type == 'BFAT':
        # get all pa ports from BFAT environment.
        return
    else:
        for pa in tl.attenuators:
            all_pa_ports_list.append(pa.attenuator_ports)
        return all_pa_ports_list


def get_ru_pa_ports(ru_index=0, fhgw_index=0, vdu_index=0, gnb_index=0):
    ru_ports_list = []
    ci_framework_type = get_builtin_value('CI_FRAMEWORK_TYPE')
    if ci_framework_type == 'BFAT':
        # get ru pa ports from BFAT environment.
        return
    else:
        if tl.gnbs[int(gnb_index)].dus[int(vdu_index)].rus:
            ru = tl.gnbs[int(gnb_index)].dus[int(vdu_index)].rus[int(ru_index)]
            for port in ru.attenuation_ports:
                ru_ports_list.append(port.port_no)
        elif tl.gnbs[int(gnb_index)].dus[int(vdu_index)].fhgws[int(fhgw_index)].rus:
            ru = tl.gnbs[int(gnb_index)].dus[int(vdu_index)].fhgws[int(fhgw_index)].rus[int(ru_index)]
            for port in ru.attenuation_ports:
                ru_ports_list.append(port.port_no)
        logger.console(ru_ports_list)
        return ru_ports_list


