def get_fhgw_credentials(gnb_index=0, vdu_index=0, fhgw_index=0):
    from taf.rfrl.cbts.utilities.generic_utils import yaml_file_to_dictionary_info
    credentials = {}

    ci_framework_type = get_builtin_value('CI_FRAMEWORK_TYPE')
    if ci_framework_type == 'BFAT':
        logger.warn('Get fhgw credentials from BFAT environment')
        pass
    else:
        logger.info('Get fhgw credentials from testline configuration')
        gnb = _get_gnb_object(gnb_id=gnb_index)
        if isinstance(gnb, CloudBts):
            fhgw = gnb.dus[int(vdu_index)].fhgws[int(fhgw_index)]
            fhgw_user_config = fhgw.user_config
            fhgw_extra_config_path = os.path.join(os.path.dirname(fhgw.user_config_path), 'fhgw_extra_config.yaml')

            credentials['fhgwid'] = fhgw_user_config['FHGW']['fhgwId']
            credentials['fhgw_ipv4_addr'] = \
                fhgw_user_config["NETWORKING"]["EXTERNAL_NET"]["NET_DOMAINS"]["NET_MANAGEMENT"]["OAM"]["IPADDRESSV4"]["ipAddress"]

            try:
                credentials['fhgw_sftp_username'] = fhgw_user_config["USERS"]["sftp_user_name"]
                credentials['fhgw_sftp_password'] = fhgw_user_config["USERS"]["sftp_user_password"]
            except KeyError as e:
                logger.info('No {} in the user config file'.format(e))

            try:
                credentials['fhgw_nemuadmin_username'] = fhgw_user_config["USERS"]["nemuadmin_user_name"]
                credentials['fhgw_nemuadmin_password'] = fhgw_user_config["USERS"]["nemuadmin_password_plain"]
            except KeyError as e:
                logger.info('No {} in the user config file'.format(e))

            if os.path.isfile(fhgw_extra_config_path):
                fhgw_extra_data = yaml_file_to_dictionary_info(fhgw_extra_config_path)
                credentials['fhgw_admin_username'] = fhgw_extra_data["users"]["service_user_name"]
                credentials['fhgw_admin_password'] = fhgw_extra_data["users"]["service_user_password"]
            else:
                try:
                    credentials['fhgw_admin_username'] = fhgw_user_config["USERS"]["admin_user_name"]
                    credentials['fhgw_admin_password'] = fhgw_user_config["USERS"]["admin_user_password_plain"]
                except KeyError as e:
                    logger.info('No {} in the user config file'.format(e))
            logger.info('get fhgw credentials info is: {}'.format(credentials))
    return credentials


