def get_ue_info_from_tl(ue_index=0, cap_index=0, data_transfer_index=0):
    if tl.ues[int(ue_index)].__class__.__name__ == "Android":
        ue_info = {
            'sn': tl.ues[int(ue_index)].serial_number,
            'cap': tl.ues[int(ue_index)].capabilities[int(cap_index)],
            'iperf_hostname': tl.ues[int(ue_index)].iperf_details.ssh_connection_details.addr,
            'iperf_username': tl.ues[int(ue_index)].iperf_details.ssh_connection_details.username,
            'iperf_password': tl.ues[int(ue_index)].iperf_details.ssh_connection_details.password,
            'control_pc_hostname': tl.ues[int(ue_index)].ssh_connection_details.addr,
            'control_pc_username': tl.ues[int(ue_index)].ssh_connection_details.username,
            'control_pc_password': tl.ues[int(ue_index)].ssh_connection_details.password

        }
    elif tl.ues[int(ue_index)].__class__.__name__ == "TafUeAndroid":
        ue_info = {
            'sn': tl.ues[int(ue_index)].serial_number,
            'cap': tl.ues[int(ue_index)].capabilities[int(cap_index)],
            'iperf_hostname': tl.ues[int(ue_index)].data_transfer[int(data_transfer_index)].app_server.address,
            'iperf_username': tl.ues[int(ue_index)].data_transfer[int(data_transfer_index)].app_server.user,
            'iperf_password': tl.ues[int(ue_index)].data_transfer[int(data_transfer_index)].app_server.password,
            'control_pc_hostname': tl.ues[int(ue_index)].ssh_connection_details.addr,
            'control_pc_username': tl.ues[int(ue_index)].ssh_connection_details.username,
            'control_pc_password': tl.ues[int(ue_index)].ssh_connection_details.password

        }
    logger.info('get ue info is:{}'.format(ue_info))
    return ue_info


def get_attenuator_info_from_tl():
    try:
        attenuator_info = tl._attenuator_info
        logger.info('get attenuator info is: {}'.format(attenuator_info))
    except Exception:
        attenuator_info = None
    return attenuator_info


def get_all_ru_sn_from_tl(vdu_index=0, gnb_index=0):
    ru_sn_list = []
    ci_framework_type = get_builtin_value('CI_FRAMEWORK_TYPE')
    if ci_framework_type == 'BFAT':
        # get ru sn from BFAT environment.
        return
    else:
        if tl.gnbs[int(gnb_index)].dus[int(vdu_index)].rus:
            rus_list = tl.gnbs[int(gnb_index)].dus[int(vdu_index)].rus
            ru_sn_list.extend([ru.serial_number for ru in rus_list])
        elif tl.gnbs[int(gnb_index)].dus[int(vdu_index)].fhgws:
            fhgw_obj_list = tl.gnbs[int(gnb_index)].dus[int(vdu_index)].fhgws
            for fhgw in fhgw_obj_list:
                rus_list = fhgw.rus
                ru_sn_list.extend([ru.serial_number for ru in rus_list])
        logger.console(ru_sn_list)
        return ru_sn_list


