def get_vcu_chart_yaml_filename(gnb_index=0):
    testline_path = tl.gnbs[int(gnb_index)].cloud_deployment.default_cfg_dir
    file_path = os.path.join(testline_path, "DEP_SCF_FILES", "CU_{}".format(gnb_index))
    logger.info(file_path)
    clusterchartfile = file_path + """/values-override.aic-vcu-cluster-preparation.yaml"""
    prerequisitechartfile = file_path + """/values-override.aic-vcu-prerequisite.yaml"""
    mainchartfile = file_path + """/values-override.aic-vcu.yaml"""
    logger.info(mainchartfile)
    if not (os.path.isfile(clusterchartfile) and os.path.isfile(prerequisitechartfile) and os.path.isfile(mainchartfile)):
        logger.error("Failed to find the yaml file in testline_configuration")
        logger.info("pnp_values-override.aic-vcu-cluster-preparation.yaml")
        return "", "", ""
    return clusterchartfile, prerequisitechartfile, mainchartfile


