def get_all_ru_sn_mac_dict_from_tl(vdu_index=0, gnb_index=0):
    ru_sn_mac_dict = {}
    ci_framework_type = get_builtin_value("CI_FRAMEWORK_TYPE")
    if ci_framework_type == "BFAT":
        # get ru sn from BFAT environment.
        return
    else:
        if tl.gnbs[int(gnb_index)].dus[int(vdu_index)].rus:
            logger.console("Get RU mac_address from vDU")
            for ru in tl.gnbs[int(gnb_index)].dus[int(vdu_index)].rus:
                ru_sn_mac_dict[ru.serial_number] = ru.mac_address
        elif tl.gnbs[int(gnb_index)].dus[int(vdu_index)].fhgws:
            logger.console("Get RU mac_address from FHGW")
            fhgw_obj_list = tl.gnbs[int(gnb_index)].dus[int(vdu_index)].fhgws
            for fhgw in fhgw_obj_list:
                rus_list = fhgw.rus
                for ru in rus_list:
                    ru_sn_mac_dict[ru.serial_number] = ru.mac_address
        return ru_sn_mac_dict
